ext('c12_eng_ch14',[
C("🧩","कठिन शब्द और अर्थ",["fast: तेज़ी से","bare: नंगा, खाली","uncertainty: अनिश्चितता","decay: क्षय, पतन"],"अब कुछ ज़रूरी शब्दों का अभ्यास करते हैं। फ़ास्ट का मतलब यहाँ तेज़ी से है। बेयर का अर्थ नंगा या ख़ाली है, जैसे पत्तों के बिना डाली। अनसर्टेंटी यानी अनिश्चितता, जब हमें आगे का पता न हो। और डिके का अर्थ क्षय या पतन है। इन शब्दों को अपने वाक्यों में उपयोग करके लिखिए, जैसे पतझड़ में पेड़ नंगे हो जाते हैं। इससे शब्द याद भी रहेंगे और उत्तर में काम भी आएँगे।"),
Q("'decay' का अर्थ और एक वाक्य बताइए।","क्षय या पतन; The decay of old buildings is sad.","अर्थ सोचिए... डिके का अर्थ है सड़ना या धीरे-धीरे बिगड़ना। पतझड़ के पत्ते भी सड़कर मिट्टी में मिल जाते हैं। यह शब्द कविता के भाव से जुड़ा है, इसलिए इसे याद रखिए।"),
C("🏠","अपने जीवन से जोड़िए",["गाँव में पतझड़ का दृश्य","आम और पीपल के पत्ते","परिवर्तन के बारे में सोचना","अपनी चिंता और आशा"],"अपने गाँव में भी पतझड़ का दृश्य देखा होगा। पीपल और आम के पुराने पत्ते झड़ते हैं और कुछ दिनों में नई कोंपलें आती हैं। इसी तरह हमारी ज़िंदगी में भी कठिन समय आता है और फिर नया समय आता है। कविता को पढ़ते हुए अपने अनुभव से जोड़िए। इससे कविता का अर्थ गहराई से समझ आएगा और आप अपने शब्दों में सुंदर उत्तर लिख पाएँगे।"),
Q("पतझड़ का दृश्य अपने गाँव से जोड़कर दो वाक्यों में लिखिए।","पीपल के पुराने पत्ते गिरते हैं और कुछ दिनों में नई कोंपलें आ जाती हैं। इसी तरह कठिन समय के बाद अच्छा समय आता है।","अपने शब्दों में सोचिए... गाँव में आम और पीपल के पत्ते झड़ते हैं और फिर नई कोंपलें फूटती हैं। यह प्रकृति का चक्र है। कठिन समय भी हमेशा नहीं रहता। इस तरह के उत्तर में आपका अपना अनुभव दिखता है, जो परीक्षक को पसंद आता है।"),
C("✅","परीक्षा से पहले अंतिम दोहराव",["कवि: ऑडेन","प्रतीक: पतझड़","स्वर: चिंताजनक","संदेश: सावधानी और आशा"],"परीक्षा से पहले चार बातें दोहरा लीजिए। कवि का नाम ऑडेन। प्रतीक पतझड़, जो गिरावट और अनिश्चितता का है। स्वर गंभीर और चिंताजनक। और संदेश यह कि हमें आने वाले संकट के प्रति सावधान रहना चाहिए, पर आशा भी बनाए रखनी चाहिए। इन चार बिंदुओं पर आधारित उत्तर आप पाँच से दस वाक्यों में आसानी से लिख सकते हैं।"),
],8)
